template:
struct Raw;
struct Authed;

struct Connection<State> {
    target: String,
    marker: State,
}

impl Connection<Raw> {
    fn new(target: &str) -> Self { Self { target: target.into(), marker: Raw } }
    fn authenticate(self) -> Connection<Authed> { Connection { target: self.target, marker: Authed } }
}

impl Connection<⟦state_bound⟧> {
    fn send(&self, msg: &str) -> String { format!("{}: {msg}", self.target) }
}

fn main() {
    let conn = Connection::new("db.local");
    let active = conn.⟦auth_call⟧;
    println!("{}", active.send("ping"));
}

tests:
#[test]
fn test_flow() {
    let conn = Connection::new("test");
    let authed = conn.authenticate();
    assert_eq!(authed.send("hello"), "test: hello");
}
